# -*- coding: utf-8 -*-# p2_flux.py - Cartographie des Flux Commerciauximport streamlit as stimport plotly.graph_objects as gofrom config import C, apply_theme, HEATMAP_SCALEfrom components.kpi_cards import section_title, page_headerfrom data.loader import load_raw, load_flux_top20from data.processor import compute_flux_heatmapdef render():    page_header(        "Cartographie des Flux",        "Top flux acheteur vers vendeur - heatmap et classement - filtres interactifs",        "🗺️"    )    df_raw = load_raw()    df_top = load_flux_top20()    with st.sidebar:        st.markdown(            "<div style='color:{};font-size:12px;margin-top:16px;'>FILTRES - FLUX</div>".format(C["muted"]),            unsafe_allow_html=True        )        n_flux = st.slider("Top N flux a afficher", 5, 20, 15, key="flux_n")        min_tx = st.slider("Transactions min.", 100, 2000, 500, step=100, key="flux_min")    section_title("Heatmap Acheteur x Vendeur", "🔥")    matrix = compute_flux_heatmap(df_raw)    fig_heat = go.Figure(go.Heatmap(        z=matrix.values,        x=matrix.columns.tolist(),        y=matrix.index.tolist(),        colorscale=HEATMAP_SCALE,        text=matrix.values.astype(int),        texttemplate="%{text}",        textfont=dict(size=10, color=C["text"]),        hovertemplate="<b>%{y}</b> vers <b>%{x}</b><br>%{z} transactions<extra></extra>",        colorbar=dict(            title=dict(                text="Nb tx",                font=dict(color=C["muted"])            ),            tickfont=dict(color=C["muted"])        ),    ))    apply_theme(fig_heat, "Volume de transactions (echantillon - proportions representatives)")    fig_heat.update_layout(height=480)    fig_heat.update_xaxes(tickangle=-35)    st.plotly_chart(fig_heat, use_container_width=True)    st.markdown(        "<p style='font-size:11px;color:{};margin-top:-8px;'>"        "Heatmap calculee sur l'echantillon de 5 000 transactions.</p>".format(C["muted"]),        unsafe_allow_html=True    )    section_title("Top {} flux internationaux classes".format(n_flux), "📊")    df_f = df_top[df_top["Nb Transactions"] >= min_tx].head(n_flux).copy()    df_f = df_f.sort_values("Nb Transactions", ascending=True)    fig_bar = go.Figure(go.Bar(        y=df_f["Flux"],        x=df_f["Nb Transactions"],        orientation="h",        marker=dict(            color=df_f["Note Globale"],            colorscale="RdYlGn",            cmin=4.75, cmax=4.87,            colorbar=dict(                title=dict(                    text="Note sat.",                    font=dict(color=C["muted"])                ),                tickfont=dict(color=C["muted"]),                x=1.01            ),            line=dict(color=C["bg"], width=0.5)        ),        text=[            "  {:,} tx - {:.3f}".format(int(v), n)            for v, n in zip(df_f["Nb Transactions"], df_f["Note Globale"])        ],        textposition="outside",        textfont=dict(color=C["text"], size=11),        hovertemplate="<b>%{y}</b><br>%{x:,} transactions<extra></extra>",    ))    apply_theme(fig_bar, "Top {} flux - couleur = note satisfaction".format(n_flux))    fig_bar.update_layout(        height=max(350, len(df_f) * 34 + 60),        margin=dict(l=10, r=120, t=55, b=20)    )    fig_bar.update_xaxes(title_text="Nombre de transactions")    st.plotly_chart(fig_bar, use_container_width=True)    section_title("Donnees detaillees", "📋")    df_display = df_top[[        "#", "Flux", "Nb Transactions", "Note Globale",        "Score Livraison", "Score Communication", "Part (%)"    ]].head(n_flux)    st.dataframe(df_display, use_container_width=True, height=min(400, len(df_display) * 37 + 40))